-- ════════════════════════════════════════════════════════════════════════════
-- DEMO DATABASE SETUP — generated by `pnpm db:build-setup`. DO NOT EDIT BY HAND
-- (except the two passwords below). ALL PATIENT DATA IN THIS FILE IS FAKE.
--
-- How to use (Supabase → SQL Editor → New query):
--   1. Paste this whole file.
--   2. Replace the two CHANGE_ME_... values in STEP 1 below with your own passwords.
--   3. Click "Run". Everything happens in one transaction: it either fully succeeds or
--      changes nothing. Safe to retry after fixing an error.
-- ════════════════════════════════════════════════════════════════════════════

begin;

-- ─── STEP 1: YOUR PASSWORDS (edit the two values in quotes) ─────────────────
create temp table setup_params (
  app_db_password text,   -- password for the restricted "clinic_app" database login (goes into Vercel's DATABASE_URL)
  demo_password text,     -- password that every demo staff account uses to sign in to the app
  demo_password_hash text,
  -- the demo week is centred on today (Riyadh)
  demo_anchor date default (now() at time zone 'Asia/Riyadh')::date
) on commit drop;

insert into pg_temp.setup_params (app_db_password, demo_password) values (
  'CHANGE_ME_APP_DB_PASSWORD',
  'CHANGE_ME_DEMO_PASSWORD'
);

-- ─── Safety checks ──────────────────────────────────────────────────────────
do $$
declare
  p record;
begin
  select * into p from pg_temp.setup_params;
  if p.app_db_password like 'CHANGE_ME%' or p.demo_password like 'CHANGE_ME%' then
    raise exception 'Please replace both CHANGE_ME_... passwords in STEP 1 before running.';
  end if;
  if length(p.app_db_password) < 16 then
    raise exception 'The clinic_app password must be at least 16 characters.';
  end if;
  if p.app_db_password !~ '^[A-Za-z0-9_-]+$' then
    raise exception 'Use only letters, numbers, - and _ in the clinic_app password (it goes inside a URL).';
  end if;
  if length(p.demo_password) < 10 then
    raise exception 'The demo staff password must be at least 10 characters.';
  end if;
  if to_regclass('public.tenants') is not null then
    raise exception 'The database is already set up (table "tenants" exists). To start over, run db/reset.sql first.';
  end if;
end $$;

create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;
update pg_temp.setup_params
  set demo_password_hash = extensions.crypt(demo_password, extensions.gen_salt('bf', 10));

-- ─── STEP 2: TABLES ─────────────────────────────────────────────────────────
-- 0000_init.sql
CREATE TYPE "public"."appointment_status" AS ENUM('pending', 'booked', 'confirmed', 'arrived', 'in_session', 'completed', 'no_show', 'cancelled');
CREATE TYPE "public"."booking_source" AS ENUM('reception', 'online', 'whatsapp');
CREATE TYPE "public"."gender" AS ENUM('male', 'female');
CREATE TYPE "public"."id_type" AS ENUM('national_id', 'iqama', 'passport');
CREATE TYPE "public"."medical_flag_kind" AS ENUM('allergy', 'contraindication', 'medication');
CREATE TYPE "public"."member_role" AS ENUM('clinic_admin', 'practitioner', 'receptionist');
CREATE TYPE "public"."note_status" AS ENUM('draft', 'signed');
CREATE TYPE "public"."payment_method" AS ENUM('cash', 'card', 'transfer');
CREATE TYPE "public"."request_status" AS ENUM('pending', 'approved', 'rejected');
CREATE TYPE "public"."session_event_kind" AS ENUM('deduction', 'override');
CREATE TABLE "accounts" (
	"id" text PRIMARY KEY NOT NULL,
	"account_id" text NOT NULL,
	"provider_id" text NOT NULL,
	"user_id" text NOT NULL,
	"access_token" text,
	"refresh_token" text,
	"id_token" text,
	"access_token_expires_at" timestamp with time zone,
	"refresh_token_expires_at" timestamp with time zone,
	"scope" text,
	"password" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE "appointments" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"branch_id" uuid NOT NULL,
	"patient_id" uuid NOT NULL,
	"service_id" uuid NOT NULL,
	"practitioner_id" uuid NOT NULL,
	"room_id" uuid NOT NULL,
	"device_id" uuid,
	"starts_at" timestamp with time zone NOT NULL,
	"ends_at" timestamp with time zone NOT NULL,
	"blocked_until" timestamp with time zone NOT NULL,
	"status" "appointment_status" DEFAULT 'booked' NOT NULL,
	"reception_note" text,
	"source" "booking_source" DEFAULT 'reception' NOT NULL,
	"demo_day_index" smallint,
	"cancel_reason" text,
	"created_by" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "appointments_tenant_id_id_key" UNIQUE("tenant_id","id"),
	CONSTRAINT "appointments_times" CHECK ("appointments"."starts_at" < "appointments"."ends_at" and "appointments"."ends_at" <= "appointments"."blocked_until")
);
CREATE TABLE "audit_logs" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"actor_user_id" text,
	"action" text NOT NULL,
	"entity_type" text NOT NULL,
	"entity_id" text,
	"metadata" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"ip_address" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE "branch_holidays" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"branch_id" uuid,
	"day" date NOT NULL,
	"name_ar" text NOT NULL,
	"name_en" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE "branches" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"name_ar" text NOT NULL,
	"name_en" text NOT NULL,
	"city_ar" text NOT NULL,
	"city_en" text NOT NULL,
	"map_url" text,
	"sort_order" smallint DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "branches_tenant_id_id_key" UNIQUE("tenant_id","id")
);
CREATE TABLE "clinical_note_addenda" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"note_id" uuid NOT NULL,
	"author_user_id" text NOT NULL,
	"author_name" text NOT NULL,
	"body" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "clinical_note_addenda_body" CHECK (length(btrim("clinical_note_addenda"."body")) > 0)
);
CREATE TABLE "clinical_notes" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"patient_id" uuid NOT NULL,
	"appointment_id" uuid,
	"author_user_id" text NOT NULL,
	"author_name" text NOT NULL,
	"body" text DEFAULT '' NOT NULL,
	"status" "note_status" DEFAULT 'draft' NOT NULL,
	"signed_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "clinical_notes_tenant_id_id_key" UNIQUE("tenant_id","id"),
	CONSTRAINT "clinical_notes_signed" CHECK (("clinical_notes"."status" = 'signed') = ("clinical_notes"."signed_at" is not null))
);
CREATE TABLE "concern_events" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"appointment_id" uuid NOT NULL,
	"conversation_id" uuid NOT NULL,
	"patient_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"body" text,
	"service_id" uuid,
	"proposed_starts_at" timestamp with time zone,
	"follow_up_appointment_id" uuid,
	"actor_user_id" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "concern_events_tenant_id_id_key" UNIQUE("tenant_id","id"),
	CONSTRAINT "concern_events_kind" CHECK ("concern_events"."kind" in ('note', 'follow_up_request', 'follow_up', 'resolved'))
);
CREATE TABLE "consent_rules" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
