  ('ce687cb8-e682-5940-9815-38d15cd2ea5a', '98ffe61e-4e6e-5cfa-b5ec-e058c0721602', '62531e32-6cf4-5dd1-9fba-5f64761380b7', 'consultation', 'استشارة طبية', 'Consultation', 20, 10, 30000, null, null, true, true, false, 'أحضر قائمة بأي أدوية أو منتجات تستخدمها حاليًا.', 'Bring a list of any medicines or skin products you use now.', null, null, null, 1),
  ('f81befe7-9561-50af-adc9-2553e96b6277', '98ffe61e-4e6e-5cfa-b5ec-e058c0721602', '62531e32-6cf4-5dd1-9fba-5f64761380b7', 'botox', 'بوتوكس', 'Botox', 30, 10, 120000, null, 'injectables', true, true, false, 'قبل الجلسة: تجنّب الأسبرين والكحول ومميّعات الدم قبل 48 ساعة إن أمكن.', 'Before the session: avoid aspirin, alcohol and blood thinners for 48 hours if possible.', 'كيف تشعر بعد جلسة البوتوكس؟ تذكّر ألا تستلقي 4 ساعات بعد الحقن.', 'How do you feel after your Botox session? Remember not to lie down for 4 hours after the injection.', 120, 2),
  ('ca94abdb-c5cc-5ac3-b91d-d621c575419b', '98ffe61e-4e6e-5cfa-b5ec-e058c0721602', '62531e32-6cf4-5dd1-9fba-5f64761380b7', 'fillers', 'فيلر', 'Fillers', 45, 15, 180000, null, 'injectables', true, true, false, 'قبل الجلسة: تجنّب مميّعات الدم قبل 48 ساعة، وأخبرنا إن كان لديك أي التهاب.', 'Before the session: avoid blood thinners for 48 hours, and tell us about any infection.', 'كيف تشعر بعد حقن الفيلر؟ التورّم الخفيف طبيعي في الأيام الأولى.', 'How do you feel after the filler? Mild swelling is normal in the first days.', 270, 3),
